package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	OrderBy  string   `json:"order_by"`
	Limit    int      `json:"limit"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func sanitizeField(field string) string {
	// Only allow known column names
	allowed := map[string]bool{"id": true, "name": true, "price": true, "sku": true, "created_at": true}
	if allowed[strings.ToLower(field)] {
		return field
	}
	return "id"
}

func buildSearchQuery(req SearchRequest) string {
	base := "SELECT id, name, price, sku FROM products WHERE 1=1"

	if req.Query != "" {
		// Text search across selected fields
		clauses := []string{}
		for _, f := range req.Fields {
			sf := sanitizeField(f)
			clauses = append(clauses, fmt.Sprintf("%s::text ILIKE '%%%s%%'", sf, req.Query))
		}
		if len(clauses) > 0 {
			base += " AND (" + strings.Join(clauses, " OR ") + ")"
		}
	}

	if req.OrderBy != "" {
		base += " ORDER BY " + sanitizeField(req.OrderBy)
	}

	if req.Limit > 0 && req.Limit <= 100 {
		base += fmt.Sprintf(" LIMIT %d", req.Limit)
	} else {
		base += " LIMIT 20"
	}

	return base
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	query := buildSearchQuery(req)
	log.Printf("Executing query: %s", query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
